package br.com.onda;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import android.view.*;import android.widget.*;
import java.io.*;import java.util.*;import java.util.concurrent.*;
/** Selection and results only; the foreground export service owns all decoding. */
@androidx.media3.common.util.UnstableApi
public class ChapterBatchExportActivity extends Activity {
 private static final int ROOT=72;private final Handler main=new Handler(Looper.getMainLooper());private final ExecutorService worker=Executors.newSingleThreadExecutor();private int generation;private boolean started,loading,busy,otherBusy,startAfterPicker,readingResults;private Uri selectedTree,source;private String stamp,title,token="";private long duration;private AudioChapterStore.Data data;private boolean[] chosen=new boolean[0];private TextView status;private Button save,quality,all,none,folder,report,other;private ProgressBar progress;private ListView list;private ArrayAdapter<String> rows;private List<ChapterBatchStore.Result> results=Collections.emptyList();
 private final ChapterExportService.Listener listener=state->{if(started&&!isDestroyed()){sync();if(state.batch!=null&&state.batch.token.equals(token)&&(state.batch.done+state.batch.failed>results.size()||!state.running))readResults();}};
 static void open(Context c,Uri source,String stamp,String title,long duration){c.startActivity(new Intent(c,ChapterBatchExportActivity.class).putExtra("source",source.toString()).putExtra("stamp",stamp).putExtra("name",title).putExtra("duration",duration));}
 @Override public void onCreate(Bundle state){super.onCreate(state);Intent input=getIntent();String value=input.getStringExtra("source");source=value==null?null:Uri.parse(value);stamp=input.getStringExtra("stamp");title=input.getStringExtra("name");duration=input.getLongExtra("duration",0);token=input.getStringExtra("batch_token");if(token==null)token="";if(token.isEmpty()){ChapterExportService.Snapshot last=ChapterExportService.state(this);if(last!=null&&last.batch!=null&&last.job.source.equals(source)&&last.job.stamp.equals(stamp))token=last.batch.token;}int[] restore=state==null?null:state.getIntArray("selected");if(state!=null){token=state.getString("token",token);String picked=state.getString("tree");if(picked!=null)selectedTree=Uri.parse(picked);startAfterPicker=state.getBoolean("startAfterPicker",false);}
  LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);Ui.background(root);root.setOnApplyWindowInsetsListener((v,i)->{root.setPadding(Ui.dp(this,16),Ui.dp(this,8)+i.getSystemWindowInsetTop(),Ui.dp(this,16),Ui.dp(this,8)+i.getSystemWindowInsetBottom());return i;});setContentView(root);LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);header.addView(Ui.button(this,"‹",v->finish()),new LinearLayout.LayoutParams(Ui.dp(this,48),-2));TextView heading=Ui.text(this,"Várias faixas em MP3",20,Ui.TEXT);heading.setMaxLines(2);header.addView(heading,new LinearLayout.LayoutParams(0,-2,1));root.addView(header);TextView collection=Ui.text(this,title==null?"Escolha uma coletânea na tela Faixas.":title,16,Ui.CYAN);collection.setMaxLines(2);collection.setEllipsize(android.text.TextUtils.TruncateAt.END);root.addView(collection);root.addView(Ui.text(this,"Marque as faixas. MP3 em Onda/Áudios; continua com tela apagada.",13,Ui.MUTED));
  LinearLayout selection=new LinearLayout(this);all=Ui.button(this,"Marcar todas",v->select(true));none=Ui.button(this,"Limpar",v->select(false));selection.addView(all,new LinearLayout.LayoutParams(0,-2,1));selection.addView(none,new LinearLayout.LayoutParams(0,-2,1));root.addView(selection);
  rows=new ArrayAdapter<String>(this,android.R.layout.simple_list_item_multiple_choice,new ArrayList<>()){@Override public View getView(int position,View recycled,ViewGroup parent){CheckedTextView view=(CheckedTextView)super.getView(position,recycled,parent);view.setTextColor(Ui.TEXT);view.setTextSize(14);view.setSingleLine(false);view.setLayoutParams(new AbsListView.LayoutParams(-1,-2));view.setPadding(Ui.dp(ChapterBatchExportActivity.this,12),Ui.dp(ChapterBatchExportActivity.this,8),Ui.dp(ChapterBatchExportActivity.this,12),Ui.dp(ChapterBatchExportActivity.this,8));view.setMinHeight(Ui.dp(ChapterBatchExportActivity.this,56));return view;}};list=new ListView(this);list.setChoiceMode(ListView.CHOICE_MODE_MULTIPLE);list.setAdapter(rows);list.setOnItemClickListener((p,v,index,id)->{if(index<chosen.length)chosen[index]=list.isItemChecked(index);controls();});root.addView(list,new LinearLayout.LayoutParams(-1,0,1));
  quality=Ui.button(this,"",v->Mp3Quality.show(this,this::controls));root.addView(quality);LinearLayout files=new LinearLayout(this);folder=Ui.button(this,"Pasta do Onda",v->{startAfterPicker=false;pickRoot();});report=Ui.button(this,"Ver resultados",v->showReport());files.addView(folder,new LinearLayout.LayoutParams(0,-2,1));files.addView(report,new LinearLayout.LayoutParams(0,-2,1));root.addView(files);progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progress.setMax(100);root.addView(progress,new LinearLayout.LayoutParams(-1,Ui.dp(this,16)));status=Ui.text(this,"Lendo as faixas salvas…",14,Ui.TEXT);root.addView(status);other=Ui.button(this,"Ver outra conversão",v->{ChapterExportService.Snapshot active=ChapterExportService.state(this);if(active!=null&&active.running)startActivity(active.screen(this));});root.addView(other);save=Ui.button(this,"Salvar selecionadas",v->{if(busy){ChapterExportService.cancel(this,ChapterExportService.state(this));return;}if(tree()==null){startAfterPicker=true;pickRoot();}else begin(tree());});Ui.primary(save);root.addView(save);load(restore);controls();
 }
 private Uri tree(){if(selectedTree!=null)return selectedTree;String value=getSharedPreferences(OndaFolders.PREF,0).getString("tree","");return value.isEmpty()?null:Uri.parse(value);}
 private void pickRoot(){try{startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION|Intent.FLAG_GRANT_PREFIX_URI_PERMISSION),ROOT);}catch(ActivityNotFoundException error){status.setText("Nenhum seletor de pastas disponível.");}}
 @Override protected void onActivityResult(int request,int result,Intent input){super.onActivityResult(request,result,input);if(request==ROOT&&result==RESULT_OK&&input!=null&&input.getData()!=null){Uri root=input.getData();try{getContentResolver().takePersistableUriPermission(root,Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);}catch(SecurityException ignored){}selectedTree=root;boolean launch=startAfterPicker;startAfterPicker=false;if(launch)begin(root);else{status.setText("Pasta escolhida. Marque as faixas e toque em Salvar selecionadas.");controls();}}}
 private void load(int[] restore){loading=true;int request=++generation;Uri uri=source;String fingerprint=stamp;String batchToken=token;worker.execute(()->{try{AudioChapterStore.Data saved=null;List<ChapterBatchStore.Result> output=Collections.emptyList();if(uri!=null&&fingerprint!=null)saved=AudioChapterStore.load(this,uri,fingerprint,duration);if(!batchToken.isEmpty())output=ChapterBatchStore.results(this,batchToken);AudioChapterStore.Data loaded=saved;List<ChapterBatchStore.Result> completed=output;main.post(()->{if(isDestroyed()||request!=generation)return;loading=false;data=loaded;results=completed;rows.clear();if(data!=null){chosen=new boolean[data.chapters.size()];for(int i=0;i<chosen.length;i++){long end=i+1<chosen.length?data.chapters.get(i+1).start:data.duration;rows.add(AudioChapterStore.label(data,i)+"\n"+AudioChaptersActivity.time(data.chapters.get(i).start)+" → "+AudioChaptersActivity.time(end));}if(restore!=null)for(int i:restore)if(i>=0&&i<chosen.length){chosen[i]=true;list.setItemChecked(i,true);}}else chosen=new boolean[0];status.setText(data==null?"Abra uma coletânea para selecionar as faixas.":"Marque as faixas que deseja salvar.");sync();});}catch(Exception error){main.post(()->{if(isDestroyed()||request!=generation)return;loading=false;status.setText(DownloadFailure.describe("Ler faixas",error));controls();});}});}
 private int count(){int n=0;for(boolean value:chosen)if(value)n++;return n;}
 private void select(boolean value){if(busy||loading||otherBusy)return;for(int i=0;i<chosen.length;i++){chosen[i]=value;list.setItemChecked(i,value);}controls();}
 private void controls(){if(save==null)return;boolean editable=!busy&&!otherBusy&&!loading&&data!=null;all.setEnabled(editable);none.setEnabled(editable);list.setEnabled(editable);quality.setText("Qualidade: "+Mp3Quality.get(this)+" kbps");quality.setEnabled(!busy&&!otherBusy&&!loading);folder.setEnabled(!busy&&!otherBusy&&!loading);report.setEnabled(!results.isEmpty());other.setVisibility(otherBusy?View.VISIBLE:View.GONE);save.setText(busy?"Cancelar seleção":"Salvar selecionadas ("+count()+")");save.setEnabled(busy||editable&&count()>0);progress.setVisibility(busy?View.VISIBLE:View.GONE);}
 private void sync(){ChapterExportService.Snapshot state=ChapterExportService.state(this);boolean own=state!=null&&state.batch!=null&&state.batch.token.equals(token);busy=own&&state.running;otherBusy=state!=null&&state.running&&!own;if(own){status.setText(state.message);progress.setIndeterminate(state.total<=0);if(state.total>0)progress.setProgress((int)Math.min(100,state.at*100/state.total));}else if(otherBusy)status.setText("Há uma conversão em andamento. Aguarde ou abra para acompanhar.");controls();}
 private void begin(Uri root){if(data==null||count()==0){status.setText("Marque pelo menos uma faixa antes de escolher a pasta.");return;}try{ChapterBatchPlan plan=ChapterBatchPlan.selected(source,root,stamp,title,data,chosen,Mp3Quality.get(this));if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},915);if(ChapterExportService.startBatch(this,plan)){token=plan.token;results=Collections.emptyList();busy=true;status.setText("Preparando pasta e conversão em segundo plano…");controls();}else{sync();status.setText("Aguarde a conversão em andamento terminar.");}}catch(IOException|RuntimeException error){status.setText(DownloadFailure.describe("Iniciar seleção",error));controls();}}
 private void readResults(){String batchToken=token;if(batchToken.isEmpty()||readingResults||isDestroyed())return;readingResults=true;worker.execute(()->{try{List<ChapterBatchStore.Result> output=ChapterBatchStore.results(this,batchToken);main.post(()->{readingResults=false;if(isDestroyed())return;if(!batchToken.equals(token)){readResults();return;}results=output;controls();});}catch(IOException ignored){main.post(()->readingResults=false);}});}
 private void showReport(){List<ChapterBatchStore.Result> output=new ArrayList<>(results);String[] names=new String[output.size()];for(int i=0;i<names.length;i++){ChapterBatchStore.Result row=output.get(i);names[i]=(row.uri!=null?"✓ ":"Falhou • ")+(row.index+1)+" • "+row.title+(row.error.isEmpty()?"":"\n"+row.error);}new AlertDialog.Builder(this).setTitle("Arquivos da seleção").setItems(names,(d,index)->{ChapterBatchStore.Result row=output.get(index);if(row.uri==null){new AlertDialog.Builder(this).setTitle(row.title).setMessage(row.error).setPositiveButton("Entendi",null).show();return;}new AlertDialog.Builder(this).setTitle(row.title).setItems(new String[]{"Ouvir no Onda","Compartilhar MP3"},(dialog,which)->{if(which==1)ShareMedia.share(this,row.uri,"audio/mpeg",row.title);else try{startActivity(new Intent(Intent.ACTION_VIEW).setClass(this,MainActivity.class).setDataAndType(row.uri,"audio/mpeg").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION));}catch(RuntimeException error){status.setText("Não foi possível abrir o MP3 salvo.");}}).setNegativeButton("Fechar",null).show();}).setNegativeButton("Fechar",null).show();}
 @Override protected void onStart(){super.onStart();started=true;ChapterExportService.listen(listener);sync();readResults();}
 @Override protected void onStop(){started=false;ChapterExportService.unlisten(listener);super.onStop();}
 @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);token=intent.getStringExtra("batch_token");if(token==null)token="";chosen=new boolean[0];data=null;selectedTree=null;startAfterPicker=false;results=Collections.emptyList();recreate();}
 @Override protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);int[] selected=new int[count()];int n=0;for(int i=0;i<chosen.length;i++)if(chosen[i])selected[n++]=i;state.putIntArray("selected",selected);state.putString("token",token);if(selectedTree!=null)state.putString("tree",selectedTree.toString());state.putBoolean("startAfterPicker",startAfterPicker);}
 @Override protected void onDestroy(){generation++;worker.shutdownNow();main.removeCallbacksAndMessages(null);super.onDestroy();}
}
